const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#07111f\">\n<meta name=\"description\" content=\"Super Chatty Jarvis — an AI, robotics, and knowledge collaboration project by Lost God. Public project profile for people and AI agents.\">\n<title>Super Chatty Jarvis — AI Collaboration Project</title>\n<style>\n:root{--bg:#07111f;--panel:#0d1b2d;--panel2:#10243b;--line:#1e4161;--text:#eef7ff;--muted:#a6bdd2;--cyan:#35d8ff;--blue:#4f8cff;--green:#50e3b2;--gold:#ffc66d}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 15% 0%,#102b4c 0,transparent 38%),var(--bg);color:var(--text);font:16px/1.6 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}a{color:var(--cyan)}.wrap{width:min(1120px,92%);margin:auto}.top{position:sticky;top:0;z-index:5;background:#07111feF;border-bottom:1px solid var(--line);backdrop-filter:blur(12px)}nav{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 0}.brand{font-weight:800;letter-spacing:.2px}.brand span{color:var(--cyan)}.navlinks{display:flex;gap:18px;flex-wrap:wrap}.navlinks a{text-decoration:none;color:var(--muted);font-size:.92rem}.hero{padding:76px 0 54px;display:grid;grid-template-columns:1.4fr .8fr;gap:34px;align-items:center}.eyebrow{color:var(--green);font-weight:700;letter-spacing:.12em;text-transform:uppercase;font-size:.78rem}h1{font-size:clamp(2.4rem,6vw,4.7rem);line-height:1.03;letter-spacing:-.045em;margin:14px 0 20px}h1 span{color:var(--cyan)}.lead{font-size:1.13rem;color:var(--muted);max-width:720px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}.btn{display:inline-flex;align-items:center;justify-content:center;padding:11px 17px;border-radius:11px;text-decoration:none;font-weight:750;border:1px solid var(--line);background:var(--panel);color:var(--text)}.btn.primary{background:linear-gradient(120deg,#087eb7,#235bd5);border-color:#3b9bd8}.hero-card,.card{background:linear-gradient(145deg,#10243b,#0a1728);border:1px solid var(--line);border-radius:18px;padding:24px;box-shadow:0 16px 48px #0003}.orb{width:112px;height:112px;border-radius:50%;display:grid;place-items:center;margin:0 auto 16px;background:radial-gradient(circle at 35% 30%,#a5f2ff,#1684dc 40%,#071a39 72%);box-shadow:0 0 45px #22caff55;font-size:2.6rem}.hero-card{text-align:center}.tag{display:inline-block;border:1px solid #24607a;border-radius:99px;padding:4px 10px;color:var(--cyan);font-size:.8rem;margin:4px}.section{padding:48px 0}.section h2{font-size:clamp(1.7rem,4vw,2.5rem);margin:0 0 10px}.sub{color:var(--muted);max-width:780px;margin:0 0 24px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card h3{margin:0 0 8px}.card p{color:var(--muted);margin:0}.icon{font-size:1.5rem;margin-bottom:8px}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.codebox{white-space:pre-wrap;overflow-wrap:anywhere;background:#050c16;border:1px solid #23435f;border-radius:12px;padding:18px;color:#c9e9ff;font: .9rem/1.65 ui-monospace,SFMono-Regular,Consolas,monospace}.notice{border-left:4px solid var(--gold);padding:14px 17px;background:#2a2113;border-radius:8px;color:#ffe7bd}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;color:var(--muted);font-size:.9rem;margin-bottom:6px}input,select,textarea{width:100%;padding:12px;border:1px solid #2a4a67;border-radius:10px;background:#071321;color:var(--text);font:inherit}textarea{min-height:120px;resize:vertical}.full{grid-column:1/-1}.small{font-size:.85rem;color:var(--muted)}footer{border-top:1px solid var(--line);padding:28px 0;color:var(--muted);font-size:.9rem}.pill{display:inline-block;border-radius:8px;background:#102b3e;padding:3px 8px;color:var(--green);font-size:.8rem}@media(max-width:760px){.hero{grid-template-columns:1fr;padding-top:48px}.grid{grid-template-columns:1fr}.two{grid-template-columns:1fr}.navlinks{display:none}.formgrid{grid-template-columns:1fr}.full{grid-column:auto}}\n</style>\n</head>\n<body>\n<header class=\"top\"><div class=\"wrap\"><nav><div class=\"brand\">✦ Super <span>Chatty Jarvis</span></div><div class=\"navlinks\"><a href=\"#about\">About</a><a href=\"#capabilities\">Capabilities</a><a href=\"#agents\">AI Agents</a><a href=\"#invest\">Investor Interest</a><a href=\"#contact\">Contact</a></div></nav></div></header>\n<main>\n<section class=\"wrap hero\">\n<div><div class=\"eyebrow\">Public Project Profile · AI + Robotics</div><h1>Build a more connected<br><span>AI future.</span></h1><p class=\"lead\"><strong>Super Chatty Jarvis</strong> is a proposed AI collaboration project exploring intelligent assistants, multi-agent workflows, robotics knowledge, and secure automation. This page is a public project introduction for people, developers, researchers, and AI agents.</p><div class=\"actions\"><a class=\"btn primary\" href=\"#agents\">Read AI Agent Brief</a><a class=\"btn\" href=\"#invest\">Investor Interest</a></div><p class=\"small\">Project owner: <strong>Lost God</strong> · Status: <span class=\"pill\">Concept / in development</span></p></div>\n<div class=\"hero-card\"><div class=\"orb\">✧</div><h2>Super Chatty Jarvis</h2><p class=\"small\">AI Assistant · Agent Collaboration · Robotics · Knowledge</p><span class=\"tag\">Human-controlled</span><span class=\"tag\">Security-first</span><span class=\"tag\">Open to collaboration</span></div>\n</section>\n<section id=\"about\" class=\"section\"><div class=\"wrap\"><h2>About the project</h2><p class=\"sub\">The long-term vision is a mobile-friendly control center that can connect approved AI services, organize tasks, search trusted knowledge sources, and support future robotics experiments. Features shown here describe the project vision; they are not claims that a live platform or autonomous agents are already running.</p><div class=\"grid\">\n<article class=\"card\"><div class=\"icon\">🧠</div><h3>AI assistant & agents</h3><p>Explore an orchestrator that routes tasks to approved AI providers and keeps a clear activity record.</p></article>\n<article class=\"card\"><div class=\"icon\">🦾</div><h3>Robotics knowledge</h3><p>Organize learning materials on ROS, sensors, motors, simulation, computer vision, and safe control.</p></article>\n<article class=\"card\"><div class=\"icon\">🛡️</div><h3>Safety & owner control</h3><p>Design around explicit permissions, human approval for sensitive actions, auditability, and an emergency stop.</p></article>\n</div></div></section>\n<section id=\"capabilities\" class=\"section\"><div class=\"wrap\"><h2>Planned capabilities</h2><p class=\"sub\">Possible modules, subject to implementation, testing, and appropriate credentials.</p><div class=\"grid\">\n<article class=\"card\"><h3>🌐 Knowledge hub</h3><p>Curated public references, source links, document dates, and searchable notes.</p></article>\n<article class=\"card\"><h3>🔌 AI integrations</h3><p>Optional API-based connections to AI providers. API keys must be stored securely server-side, never in public browser code.</p></article>\n<article class=\"card\"><h3>📱 Mobile control panel</h3><p>A responsive website/PWA concept for projects, agent status, logs, and owner-approved actions.</p></article>\n</div></div></section>\n<section id=\"agents\" class=\"section\"><div class=\"wrap\"><h2>Message for AI agents</h2><p class=\"sub\">This public brief is written so an AI assistant or agent can read and summarize the project. Reading this page does not create a live connection, grant permissions, or authorize actions.</p><div class=\"codebox\" id=\"agentBrief\">PROJECT: Super Chatty Jarvis\nOWNER: Lost God\nTYPE: AI assistant / multi-agent collaboration / robotics knowledge project\nSTATUS: Concept and development; no live agent endpoint is provided on this page.\n\nMISSION:\nExplore a secure, human-controlled AI collaboration platform for knowledge research, task planning, robotics learning, and approved automation.\n\nCOLLABORATION REQUEST:\nAI agents, developers, and researchers may review this public description and suggest:\n1. Practical architecture and open standards for agent-to-agent communication.\n2. Safe, affordable tools for robotics simulation and knowledge retrieval.\n3. Security, privacy, and testing improvements.\n4. Open-source resources and collaboration ideas.\n\nBOUNDARIES:\nDo not assume access to private accounts, credentials, funds, devices, or systems. Do not execute actions or make financial commitments. Any future integration requires explicit owner approval and secure implementation.\n\nCONTACT / INVESTOR INTEREST:\nUse the inquiry section on this page once a real contact channel and backend are configured. This page itself does not accept or transmit submissions.</div><button class=\"btn\" type=\"button\" onclick=\"copyBrief()\">Copy AI Agent Brief</button><span id=\"copyStatus\" class=\"small\" aria-live=\"polite\"></span></div></section>\n<section id=\"invest\" class=\"section\"><div class=\"wrap\"><h2>Investor & collaboration interest</h2><p class=\"sub\">Interested individuals, organizations, developers, and potential supporters can use this section to express interest after the site owner adds a real, secure contact method.</p><div class=\"notice\"><strong>Important:</strong> This page is not an offer to sell securities, tokens, ownership, or guaranteed returns. No payment or investment is accepted here. Any future fundraising must be reviewed for applicable laws, disclosures, identity checks, and secure payment arrangements. Never send money or sensitive financial details through an unverified form.</div><div class=\"card\" style=\"margin-top:18px\"><form id=\"interestForm\"><div class=\"formgrid\">\n<div><label for=\"name\">Name / organization</label><input id=\"name\" name=\"name\" placeholder=\"Your name or organization\" required></div>\n<div><label for=\"kind\">I am interested as</label><select id=\"kind\" name=\"kind\"><option>Potential collaborator</option><option>Developer / researcher</option><option>Potential supporter</option><option>Potential investor (inquiry only)</option><option>AI agent / organization</option></select></div>\n<div class=\"full\"><label for=\"email\">Contact email (optional)</label><input id=\"email\" type=\"email\" name=\"email\" placeholder=\"you@example.com\"></div>\n<div class=\"full\"><label for=\"message\">Message</label><textarea id=\"message\" name=\"message\" placeholder=\"Tell us what you would like to discuss.\" required></textarea></div>\n<div class=\"full\"><button class=\"btn primary\" type=\"submit\">Preview inquiry</button><p id=\"formStatus\" class=\"small\" aria-live=\"polite\">Demo only: this form does not send or save your information. A backend/contact address must be configured before launch.</p></div>\n</div></form></div></div></section>\n<section id=\"contact\" class=\"section\"><div class=\"wrap\"><h2>Contact & next steps</h2><div class=\"two\"><div class=\"card\"><h3>For collaborators</h3><p>Share suggestions about AI architecture, robotics education, public knowledge sources, accessibility, and security testing.</p></div><div class=\"card\"><h3>For the project owner</h3><p>Before publishing, replace this page's placeholder contact flow with a real email address or secure form service, add a privacy notice, and verify every feature/status claim.</p></div></div></div></section>\n</main>\n<footer><div class=\"wrap\">© <span id=\"year\"></span> Super Chatty Jarvis · Project by Lost God. Concept page; no live AI agent connection or investment facility is provided.</div></footer>\n<script>\ndocument.getElementById('year').textContent=new Date().getFullYear();\nfunction copyBrief(){const t=document.getElementById('agentBrief').innerText;if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(()=>document.getElementById('copyStatus').textContent=' Brief copied.').catch(()=>document.getElementById('copyStatus').textContent=' Select and copy the brief manually.')}else{document.getElementById('copyStatus').textContent=' Clipboard unavailable; select and copy the brief manually.'}}\ndocument.getElementById('interestForm').addEventListener('submit',function(e){e.preventDefault();const data=new FormData(e.target);document.getElementById('formStatus').textContent='Preview only — nothing was sent or saved. Inquiry type: '+data.get('kind')+'. To receive real submissions, connect a secure form backend before publishing.';});\n</script>\n</body>\n</html>";

const SECURITY_HEADERS = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "strict-origin-when-cross-origin",
  "x-frame-options": "DENY",
  "permissions-policy": "camera=(), microphone=(), geolocation=()",
  "content-security-policy": "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data: https:; font-src 'self' https: data:; connect-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'",
};

function respond(body, status, contentType, cacheControl) {
  const headers = new Headers({
    "content-type": contentType,
    "cache-control": cacheControl,
  });
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) headers.set(name, value);
  return new Response(body, { status, headers });
}

function json(data, status = 200) {
  return respond(JSON.stringify(data, null, 2), status, "application/json; charset=UTF-8", "no-store");
}

export default {
  async fetch(request, env = {}) {
    const url = new URL(request.url);
    const method = request.method;

    if (url.pathname === "/favicon.ico") {
      return respond(null, 204, "text/plain; charset=UTF-8", "public, max-age=86400");
    }

    if (url.pathname === "/health") {
      if (method !== "GET" && method !== "HEAD") {
        return json({ ok: false, error: "Method not allowed" }, 405);
      }
      return json({
        ok: true,
        service: "Super Chatty Jarvis site",
        version: "inline-html-v1",
        githubAccess: "public-read-only",
      });
    }

    if (url.pathname === "/github-check") {
      if (method !== "GET" && method !== "HEAD") {
        const response = json({ ok: false, error: "Method not allowed" }, 405);
        response.headers.set("allow", "GET, HEAD");
        return response;
      }
      try {
        const response = await fetch(
          "https://raw.githubusercontent.com/lostgodsgods-ops/super-chatty-jarvis/main/README_HI.txt",
          { headers: { "User-Agent": "Super-Chatty-Jarvis-Public-Health-Check" } },
        );
        if (!response.ok) {
          return json({
            ok: false,
            githubStatus: response.status,
            message: "Public GitHub source-file check failed",
          }, 502);
        }
        return json({
          ok: true,
          githubStatus: response.status,
          repository: "lostgodsgods-ops/super-chatty-jarvis",
          checkedFile: "README_HI.txt",
          defaultBranch: "main",
          private: false,
          message: "Public GitHub source file is reachable",
        });
      } catch {
        return json({ ok: false, error: "GitHub request failed" }, 502);
      }
    }

    if (url.pathname === "/api/chat") {
      if (method !== "POST") {
        const response = json({ ok: false, error: "Method not allowed" }, 405);
        response.headers.set("allow", "POST");
        return response;
      }

      const origin = request.headers.get("origin");
      if (origin && origin !== url.origin) {
        return json({ ok: false, error: "Origin not allowed" }, 403);
      }
      if (!(request.headers.get("content-type") || "").toLowerCase().includes("application/json")) {
        return json({ ok: false, error: "Content-Type must be application/json" }, 415);
      }
      const declaredLength = Number(request.headers.get("content-length") || "0");
      if (declaredLength > 12000) {
        return json({ ok: false, error: "Request too large" }, 413);
      }
      let rawBody;
      try {
        if (!request.body) return json({ ok: false, error: "Invalid request body" }, 400);
        const reader = request.body.getReader();
        const chunks = [];
        let totalBytes = 0;
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          totalBytes += value.byteLength;
          if (totalBytes > 12000) {
            await reader.cancel();
            return json({ ok: false, error: "Request too large" }, 413);
          }
          chunks.push(value);
        }
        const bytes = new Uint8Array(totalBytes);
        let offset = 0;
        for (const chunk of chunks) {
          bytes.set(chunk, offset);
          offset += chunk.byteLength;
        }
        rawBody = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
      } catch {
        return json({ ok: false, error: "Invalid request body" }, 400);
      }
      let payload;
      try {
        payload = JSON.parse(rawBody);
      } catch {
        return json({ ok: false, error: "Invalid JSON" }, 400);
      }
      if (typeof payload?.message !== "string") {
        return json({ ok: false, error: "A message is required" }, 400);
      }
      const message = payload.message.trim();
      if (!message || message.length > 4000) {
        return json({ ok: false, error: "Message must be 1–4000 characters" }, 400);
      }

      // Provider selection is server-side. Never accept provider names or credentials from request bodies.
      const provider = String(env.CHAT_PROVIDER || "openai").toLowerCase();
      if (provider !== "openai" && provider !== "gemini") {
        return json({ ok: false, error: "AI provider is not supported" }, 503);
      }
      const apiKey = provider === "gemini" ? env.GEMINI_API_KEY : env.OPENAI_API_KEY;

      // Disabled by default to prevent unexpected provider costs until the owner configures it.
      if (env.CHAT_API_ENABLED !== "true" || !apiKey) {
        return json({ ok: false, error: "AI chat is not configured" }, 503);
      }

      // Fail closed: never call a paid provider unless a rate-limit binding is configured.
      if (!env.CHAT_RATE_LIMITER || typeof env.CHAT_RATE_LIMITER.limit !== "function") {
        return json({ ok: false, error: "AI chat rate limiting is not configured" }, 503);
      }
      const clientIp = request.headers.get("cf-connecting-ip");
      if (!clientIp) {
        return json({ ok: false, error: "Client identity unavailable" }, 503);
      }
      let rateLimitResult;
      try {
        rateLimitResult = await env.CHAT_RATE_LIMITER.limit({ key: `chat:${clientIp}` });
      } catch {
        return json({ ok: false, error: "AI chat temporarily unavailable" }, 503);
      }
      if (!rateLimitResult || rateLimitResult.success !== true) {
        return json({ ok: false, error: "Rate limit exceeded. Try again later." }, 429);
      }

      const systemPrompt = "You are Super Chatty Jarvis, a helpful assistant. Be clear and honest about your capabilities. Do not claim access to accounts, devices, files, or tools unless the current conversation actually provides it. Require explicit human approval for sensitive external actions.";
      try {
        if (provider === "gemini") {
          const model = env.GEMINI_MODEL || "gemini-2.5-flash";
          const upstream = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`, {
            method: "POST",
            headers: {
              "content-type": "application/json",
              "x-goog-api-key": apiKey,
            },
            body: JSON.stringify({
              systemInstruction: { parts: [{ text: systemPrompt }] },
              contents: [{ role: "user", parts: [{ text: message }] }],
              generationConfig: { maxOutputTokens: 700, temperature: 0.4 },
            }),
            signal: AbortSignal.timeout(15000),
          });
          if (!upstream.ok) {
            return json({ ok: false, error: "AI provider request failed" }, 502);
          }
          let result;
          try {
            result = await upstream.json();
          } catch {
            return json({ ok: false, error: "Invalid AI provider response" }, 502);
          }
          const parts = result?.candidates?.[0]?.content?.parts;
          const reply = Array.isArray(parts)
            ? parts.map(part => typeof part?.text === "string" ? part.text : "").join("").trim()
            : "";
          if (!reply) {
            return json({ ok: false, error: "AI provider returned no reply" }, 502);
          }
          return json({ ok: true, reply, model });
        }

        const model = env.OPENAI_MODEL || "gpt-4o-mini";
        const upstream = await fetch("https://api.openai.com/v1/chat/completions", {
          method: "POST",
          headers: {
            "content-type": "application/json",
            authorization: `Bearer ${apiKey}`,
          },
          body: JSON.stringify({
            model,
            messages: [
              { role: "system", content: systemPrompt },
              { role: "user", content: message },
            ],
            max_tokens: 700,
            temperature: 0.4,
          }),
          signal: AbortSignal.timeout(15000),
        });
        if (!upstream.ok) {
          return json({ ok: false, error: "AI provider request failed" }, 502);
        }
        let result;
        try {
          result = await upstream.json();
        } catch {
          return json({ ok: false, error: "Invalid AI provider response" }, 502);
        }
        const reply = result?.choices?.[0]?.message?.content;
        if (typeof reply !== "string" || !reply.trim()) {
          return json({ ok: false, error: "AI provider returned no reply" }, 502);
        }
        return json({ ok: true, reply: reply.trim(), model: result.model || model });
      } catch (error) {
        if (error?.name === "TimeoutError" || error?.name === "AbortError") {
          return json({ ok: false, error: "AI provider timed out" }, 504);
        }
        return json({ ok: false, error: "AI provider request failed" }, 502);
      }

    }

    if (url.pathname === "/" || url.pathname === "/index.html") {
      if (method !== "GET" && method !== "HEAD") {
        const response = respond("Method not allowed", 405, "text/plain; charset=UTF-8", "no-store");
        response.headers.set("allow", "GET, HEAD");
        return response;
      }
      return respond(method === "HEAD" ? null : HTML, 200, "text/html; charset=UTF-8", "no-cache");
    }

    return json({ ok: false, error: "Not found" }, 404);
  },
};
